mapper.select:
select c.`id`, c.`origin_id`, c.`expert_uid`, c.`pro_id`, c.`task_id`, c.`reason`, c.`prev_pro_stat`, c.`created`, c.`confirmed_time`,
    qa.`topic_name` as topicName,
    qa.`group_name` as groupName,
    qa.`apply_id` as proCode,
    pro.`qc_group_name` as qcGroupName,
    (SELECT sd.name FROM sys_dept sd JOIN sys_user su ON sd.dept_id = su.dept_id WHERE su.user_id = qa.opt_uid LIMIT 1) as companyName,
    (SELECT su.name FROM sys_user su WHERE su.user_id = c.expert_uid LIMIT 1) as expertName
from ass_qc_expert_eliminate_confirmed c
left join ass_qc_group_apply_info qa on c.pro_id = qa.pro_id and c.task_id = qa.task_id
left join ass_award_enterprise_project pro on c.pro_id = pro.id

     and c.id = #{id} 
     and c.expert_uid = #{expertUid} 
     and c.pro_id = #{proId} 
     and c.task_id = #{taskId} 
     and pro.qc_group_name = #{qcGroupName} 

order by c.id desc

    limit ${offset}, ${limit}

select count(*) from ass_qc_expert_eliminate_confirmed

     and id = #{id} 
     and expert_uid = #{expertUid} 
     and pro_id = #{proId} 
     and task_id = #{taskId}
